{
  "probability": 0.16,
  "range_low": 0.10,
  "range_high": 0.22,
  "summary": [
    "Anchor from near-term state-actor chemical weapons risk in Ukraine around 12%.",
    "Documented battlefield presence of riot-control agents (CS/chloropicrin) and credible intel alleging Russian involvement push the posterior up.",
    "OPCW monitoring and the normative prohibition reduce risk, constraining the posterior.",
    "Delivery challenges and attribution uncertainties keep the probability non-negligible but not large, consistent with a 16% posterior for the 2025-2026 horizon."
  ],
  "confidence": "medium",
  "narrative": "Starting from a baseline near-term risk anchored at about 12%, the evidence nudges the probability upward due to CS detections and intelligence claims, but strong norms and practical constraints pull it back. The resulting calibrated estimate places the chance of any state actor using chemical weapons in Ukraine before May 1, 2026 at roughly 16% with a ±6 percentage point uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Reference-class anchor: state-actor chemical weapons use in modern warfare with a near-term horizon; base rate around 12% based on Swift Centre and related forecasts for the next 12 months."
    },
    "factor_updates": [
      {
        "factor": "Documented battlefield presence of riot-control chemical agents (CS/chloropicrin)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "OPCW-confirmed detections on trenches and samples indicate real battlefield chemical exposure, elevating near-term risk."
      },
      {
        "factor": "Credible intelligence allegations of Russia's use of chloropicrin/CS",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Public statements by US/EU intelligence raise the expected signal of state-actor use, though attribution remains contested."
      },
      {
        "factor": "OPCW monitoring and Chemical Weapons Convention norms",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Active deterrence and international law reduce the probability of use in the near term."
      },
      {
        "factor": "Delivery feasibility and deterrence concerns",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Practical hurdles and political costs constrain use, particularly in the near term."
      },
      {
        "factor": "Attribution uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Even with some CS detections and claims, uncertainty about who is responsible tempers the signaling strength."
      }
    ],
    "synthesis_rationale": "Base rate anchor combined with modest upweight from battlefield detections and credible assertions, offset by norms, deterrence, and logistics; the horizon constraint (≤May 1 2026) further reduces the posterior, yielding a calibrated 16% with a wide but plausible uncertainty band. Calibration notes: 2-sided range is intentionally conservative given evidence quality and attribution ambiguity."
  }
}

